CREATE TABLE shipments(id BIGSERIAL PRIMARY KEY,order_id BIGINT NOT NULL UNIQUE,buyer_id BIGINT NOT NULL,farmer_ids TEXT,logistics_user_id BIGINT,pickup_address TEXT NOT NULL,delivery_address TEXT NOT NULL,status VARCHAR(20) NOT NULL,estimated_delivery TIMESTAMP WITH TIME ZONE,shipped_at TIMESTAMP WITH TIME ZONE,delivered_at TIMESTAMP WITH TIME ZONE,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE shipment_status_history(id BIGSERIAL PRIMARY KEY,shipment_id BIGINT NOT NULL REFERENCES shipments(id),from_status VARCHAR(20),to_status VARCHAR(20) NOT NULL,changed_by BIGINT,changed_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE outbox_events(id UUID PRIMARY KEY,aggregate_type VARCHAR(100) NOT NULL,aggregate_id VARCHAR(100) NOT NULL,event_type VARCHAR(100) NOT NULL,event_version INTEGER NOT NULL,payload JSONB NOT NULL,status VARCHAR(30) NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMP WITH TIME ZONE NOT NULL,published_at TIMESTAMP WITH TIME ZONE,last_error TEXT);
CREATE TABLE processed_events(event_id UUID PRIMARY KEY,processed_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_shipments_logistics ON shipments(logistics_user_id);CREATE INDEX idx_shipments_buyer ON shipments(buyer_id);
